-- V_MAJ_CAT_TREND_PSF: V_MAJ_CAT_TREND (store + MAJ-CAT grain) + space-plan density/APF, with per-day area KPIs.
-- Same logic as V_TREND_AVG_PSF (17_v_trend_avg_psf.sql):
--   PPA = FINAL DENSITY / APF   (space plan matched on STORE_CODE + MAJ-CAT)
--   FINAL_AREA_<date> = STK_Q * PPA
--   SALE_PSF_<date>   = SALE_V / FINAL_AREA
--   GP_PSF_<date>     = SALE_GM / FINAL_AREA
--   STR_<date>        = STK_V / (SALE_V - SALE_GM)
-- Each date keeps its raw STK_Q/STK_V/SALE_Q/SALE_V/SALE_GM next to the KPIs.
-- Missing values and divide-by-zero come out as 0, never NULL.
-- Dates are hard-coded to V_MAJ_CAT_TREND's columns (2026-09-15 .. 2026-10-15);
-- regenerate this file if that view is rebuilt with a different date range.
-- Average PSF columns (placed right after PPA, before the per-day columns):
--   <KPI>_MTD = 2026-10-01 .. 2026-10-15,  <KPI>_L7D = 2026-10-09 .. 2026-10-15,
--   <KPI>_30D = 2026-09-16 .. 2026-10-15,  <KPI>_TD  = 2026-10-15 (that day's value)
--   for KPI = SALE_PSF, GP_PSF and STR. An average only counts the days whose value is > 0:
--   sum of those days / number of those days (0 when there are none).

CREATE OR REPLACE VIEW V2RETAIL.SILVER.V_MAJ_CAT_TREND_PSF AS
WITH SP AS (
    SELECT ST_CD, MAX(APF) AS APF
    FROM V2RETAIL.AKS_GOLD.SPACE_PLAN_OCT_20261007_142428
    GROUP BY ST_CD
),
BASE AS (
    SELECT COALESCE(D."FINAL DENSITY", 0) AS FINAL_DENSITY,
           COALESCE(S.APF, 0)             AS APF,
           COALESCE(DIV0NULL(D."FINAL DENSITY", S.APF), 0) AS PPA,
           A.*
    FROM V2RETAIL.SILVER.V_MAJ_CAT_TREND A
    LEFT JOIN SP S
           ON A.STORE_CODE = S.ST_CD
    LEFT JOIN V2RETAIL.AKS_GOLD.SPACE_PLAN_OCT_20261007_142428 D
           ON A.STORE_CODE = D.ST_CD
          AND A."MAJ-CAT"  = D.MAJ_CAT
),
DAYS AS (
SELECT SEG, DIV, "SUB-DIV", STORE_CODE, "MAJ-CAT",
       FINAL_DENSITY, APF, PPA,
       -- 2026-09-15
       COALESCE("2026-09-15_STK_Q", 0) AS "2026-09-15_STK_Q",
       COALESCE("2026-09-15_STK_V", 0) AS "2026-09-15_STK_V",
       COALESCE("2026-09-15_SALE_Q", 0) AS "2026-09-15_SALE_Q",
       COALESCE("2026-09-15_SALE_V", 0) AS "2026-09-15_SALE_V",
       COALESCE("2026-09-15_SALE_GM", 0) AS "2026-09-15_SALE_GM",
       COALESCE("2026-09-15_STK_Q", 0) * PPA AS FINAL_AREA_2026_09_15,
       COALESCE(DIV0NULL("2026-09-15_SALE_V", COALESCE("2026-09-15_STK_Q", 0) * PPA), 0) AS SALE_PSF_2026_09_15,
       COALESCE(DIV0NULL("2026-09-15_SALE_GM", COALESCE("2026-09-15_STK_Q", 0) * PPA), 0) AS GP_PSF_2026_09_15,
       COALESCE(DIV0NULL("2026-09-15_STK_V", COALESCE("2026-09-15_SALE_V", 0) - COALESCE("2026-09-15_SALE_GM", 0)), 0) AS STR_2026_09_15,
       -- 2026-09-16
       COALESCE("2026-09-16_STK_Q", 0) AS "2026-09-16_STK_Q",
       COALESCE("2026-09-16_STK_V", 0) AS "2026-09-16_STK_V",
       COALESCE("2026-09-16_SALE_Q", 0) AS "2026-09-16_SALE_Q",
       COALESCE("2026-09-16_SALE_V", 0) AS "2026-09-16_SALE_V",
       COALESCE("2026-09-16_SALE_GM", 0) AS "2026-09-16_SALE_GM",
       COALESCE("2026-09-16_STK_Q", 0) * PPA AS FINAL_AREA_2026_09_16,
       COALESCE(DIV0NULL("2026-09-16_SALE_V", COALESCE("2026-09-16_STK_Q", 0) * PPA), 0) AS SALE_PSF_2026_09_16,
       COALESCE(DIV0NULL("2026-09-16_SALE_GM", COALESCE("2026-09-16_STK_Q", 0) * PPA), 0) AS GP_PSF_2026_09_16,
       COALESCE(DIV0NULL("2026-09-16_STK_V", COALESCE("2026-09-16_SALE_V", 0) - COALESCE("2026-09-16_SALE_GM", 0)), 0) AS STR_2026_09_16,
       -- 2026-09-17
       COALESCE("2026-09-17_STK_Q", 0) AS "2026-09-17_STK_Q",
       COALESCE("2026-09-17_STK_V", 0) AS "2026-09-17_STK_V",
